from moler.cmd.unix.exit import Exit as UnixExit


class Exit(UnixExit):
    """Exit command class."""

    def __init__(self, connection, prompt=None, expected_prompt=r'emssim@tty-server\d+:.*\$', newline_chars=None,
                 runner=None, target_newline="\n", **kwargs):
        """
        Exit command.

        :param connection: connection to device.
        :param expected_prompt: prompt on device changed by this command.
        :param prompt: expected prompt sending by device after command execution. Maybe String or compiled re.
        :param newline_chars:  new line chars on device (a list).
        :param runner: runner to run command.
        :param target_newline: newline on device when command is finished and prompt is changed.
        """
        super(Exit, self).__init__(connection=connection, prompt=prompt, expected_prompt=expected_prompt,
                                   newline_chars=newline_chars, target_newline=target_newline, runner=runner, **kwargs)

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "exit"
        return cmd


COMMAND_OUTPUT = """exit
emssim@tty-server199:~ $"""

